// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address user, address ward) public {
        vm.assume(user != address(0));
        vm.assume(ward != address(0));
        vm.assume(ward != user);

        vm.prank(address(this));
        c.rely(ward);

        vm.prank(ward);
        try c.rely(user) { } catch { }

        assertTrue(c.wards(user) == 1);
    }
}
